import{_ as r,o as a,c as o,a2 as e}from"./chunks/framework.BcSf7okB.js";const m=JSON.parse('{"title":"机械方向","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mechanical.md","filePath":"guide/mechanical.md"}'),l={name:"guide/mechanical.md"};function i(n,t,s,d,h,c){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="机械方向" tabindex="-1">机械方向 <a class="header-anchor" href="#机械方向" aria-label="Permalink to &quot;机械方向&quot;">​</a></h1><blockquote><p>🛠️ 负责机器人的 <strong>结构设计、强度校核、加工装配、减重优化</strong></p></blockquote><hr><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><h3 id="第一阶段-基础入门" tabindex="-1">第一阶段：基础入门 <a class="header-anchor" href="#第一阶段-基础入门" aria-label="Permalink to &quot;第一阶段：基础入门&quot;">​</a></h3><ol><li><strong>SolidWorks 基础操作</strong>：草图绘制、特征建模、装配体</li><li><strong>工程制图</strong>：三视图、尺寸标注、公差配合</li><li><strong>材料基础</strong>：铝合金、碳纤维、3D 打印材料特性</li><li><strong>加工认知</strong>：CNC、线切割、3D 打印、手板制作</li></ol><h3 id="第二阶段-专业进阶" tabindex="-1">第二阶段：专业进阶 <a class="header-anchor" href="#第二阶段-专业进阶" aria-label="Permalink to &quot;第二阶段：专业进阶&quot;">​</a></h3><ol><li><strong>力学分析</strong>：材料力学、理论力学基础</li><li><strong>有限元分析 (FEA)</strong>：ANSYS/SolidWorks Simulation 静力学分析</li><li><strong>传动设计</strong>：齿轮、同步带、丝杆选型计算</li><li><strong>减重设计</strong>：拓扑优化、镂空设计、材料替换</li></ol><h3 id="第三阶段-实战应用" tabindex="-1">第三阶段：实战应用 <a class="header-anchor" href="#第三阶段-实战应用" aria-label="Permalink to &quot;第三阶段：实战应用&quot;">​</a></h3><ol><li><strong>底盘设计</strong>：麦克纳姆轮底盘（RM2027：600×600×600mm 尺寸限制）、悬挂系统</li><li><strong>云台设计</strong>：二轴云台、重心配平</li><li><strong>发射机构</strong>：42mm 摩擦轮发射（RM2027：独立热量管理、400×400×400mm 尺寸）、17mm 拨弹机构</li><li><strong>整机装配</strong>：模块化设计、走线规划、重量控制（英雄42mm机构 ≤6kg）</li></ol><hr><h2 id="推荐软件" tabindex="-1">推荐软件 <a class="header-anchor" href="#推荐软件" aria-label="Permalink to &quot;推荐软件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>软件</th><th>用途</th><th>学习资源</th></tr></thead><tbody><tr><td><strong>SolidWorks 2022+</strong></td><td>3D 建模主力</td><td>B 站 &quot;SolidWorks 教程&quot;，官方认证</td></tr><tr><td><strong>AutoCAD</strong></td><td>2D 工程图</td><td>学堂在线 CAD 课程</td></tr><tr><td><strong>ANSYS Workbench</strong></td><td>有限元分析</td><td>知乎专栏教程</td></tr><tr><td><strong>Fusion 360</strong></td><td>概念设计、3D 打印</td><td>Autodesk 官方教程</td></tr></tbody></table><hr><h2 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to &quot;参考资源&quot;">​</a></h2><ul><li><a href="https://sjtu-robomaster-team.github.io/SolidWorks-learning/" target="_blank" rel="noreferrer">上海交大机械部培训教程（SolidWorks）</a></li><li><a href="https://www.robomaster.com/zh-CN/products/components/referee" target="_blank" rel="noreferrer">RoboMaster 裁判系统结构图纸（STEP）</a></li><li><a href="https://bbs.robomaster.com/" target="_blank" rel="noreferrer">RM 开源机械设计汇总（社区）</a></li></ul><hr><h2 id="新人任务清单" tabindex="-1">新人任务清单 <a class="header-anchor" href="#新人任务清单" aria-label="Permalink to &quot;新人任务清单&quot;">​</a></h2><ul><li>[ ] 安装 SolidWorks 并完成基础建模教程</li><li>[ ] 设计一个简单的零件（如电机座）并出工程图</li><li>[ ] 了解麦克纳姆轮底盘的运动学原理</li><li>[ ] 学习一种加工方式（3D 打印/CNC）</li><li>[ ] 参与一次战队机器人装配</li></ul>',19)])])}const u=r(l,[["render",i]]);export{m as __pageData,u as default};
